def grid_of(g):
    H,W=len(g),len(g[0])
    rows_lines=[r for r in range(H) if all(x==g[r][0] and x!=0 for x in g[r])]
    cols_lines=[c for c in range(W) if all(g[r][c]==g[0][c] and g[r][c]!=0 for r in range(H))]
    rb=[-1]+rows_lines+[H]; cb=[-1]+cols_lines+[W]
    # interior cells: consecutive runs between lines
    bands_r=[]; prev=0
    for l in rows_lines+[H]:
        if l>prev: bands_r.append((prev,l-1))
        prev=l+1
    bands_c=[]; prev=0
    for l in cols_lines+[W]:
        if l>prev: bands_c.append((prev,l-1))
        prev=l+1
    return rows_lines,cols_lines,bands_r,bands_c

