def bands_of(g):
    H,W=len(g),len(g[0])
    rs=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=0]
    cs=[c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]!=0]
    rb=[(0,rs[0]-1),(rs[0]+1,rs[1]-1)] if len(rs)>=2 else [(0,H-1)]
    # generalize: split by separators
    def split(sep_list,maxidx):
        pts=[-1]+sep_list+[maxidx]
        out=[]
        prev=pts[0]
        for p in pts[1:]:
            if p>prev+1: out.append((prev+1,p))
            prev=p
        return out
    return split(rs,H-1),split(cs,W-1)
