def solve(g,sepc=None):
    H,W=len(g),len(g[0])
    rs=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=0]
    cs=[c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]!=0]
    rb=[];prev=0
    for s in rs+[H]:
        if s>prev+1: rb.append((prev,s-1))
        prev=s+1
    cb=[];prev=0
    for s in cs+[W]:
        if s>prev+1: cb.append((prev,s-1))
        prev=s+1
    # shape cells: any nonzero non-separator cell; per-color components
    cells=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c] not in (0,) and g[r][c]!=g[rs[0]][rs[0]] if False]
    sepc=g[rs[0]] if rs else g[cs[0]] if cs else None
    shp=[(r,c,v) for r in range(H) for c in range(W) if g[r][c] not in (0,sepc)]
    out=[row[:] for row in g]
    def ref_cells(seplines,direction):
        res={}
        for (a,b) in lines:
            for (r,c,v) in shp:
                nr,nc=r,c
                if direction=='h':
                    # reflect across separator row s: r' = 2s - r
                    for s in rs:
                        nr=2*s-r; nc=c
                        if 0<=nr<H and 0<=nc<W and g[nr][nc]==0 and (nr,nc)!=(r,c):
                            res[(s,nr,nc)]=v
                elif direction=='v':
                    for s in cs:
                        nc=2*s-c; nr=r
                        if 0<=nr<H and 0<=nc<W and g[nr][nc]==0 and (nr,nc)!=(r,c):
                            res[(s,nr,nc)]=v
        return res
    applied=set()
    for _ in range(4):
        hit=False
        cand_h=ref_cells(rs,'h'); cand_v=ref_cells(cs,'v')
        for key in cand_h|cand_v:
            s,nr,nc=key; v=cand_h.get(key) or cand_v.get(key)
            if (nr,nc) in applied: continue
            # requires overlap with existing shape (before this pass)
            ov=[(r,c) for r,c,vv in shp if any((abs(r-nr)+abs(c-nc))==0 or True)]
            # determine if this reflection overlaps existing shape cells anywhere
            reflset={(r,c) for (s_,r2,c2),vv in [(x[0],x[1],x[2]) for x in []]}
            ok=False
            # reconstruct: is there any shape cell mapping here under this line's transform?
            for (r,c,vv) in shp:
                rr,cc=r,c
                if direction=='h':
                    rr=2*key[0]-r; cc=c
                else:
                    rr=r; cc=2*key[1]-c
                if (rr,cc)==(nr,nc): ok=True
            if ok:
                out[nr][nc]=v; applied.add((nr,nc)); hit=True
        if not hit: break
    return out
