    seen=set(); out=[]
    H,W=len(g),len(g[0])
    for r in range(H):
        for c in range(W):
            if g[r][c]==color and (r,c) not in seen:
                st=[(r,c)];seen.add((r,c));comp=[]
                while st:
                    a,b=st.pop();comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
