def analyze(gi):
    h,w=len(gi),len(gi[0])
    fr=[r for r,row in enumerate(gi) if all(v==8 for v in row)]
    fc=[c for c in range(w) if all(gi[r][c]==8 for r in range(h))]
    rbands=[]; prev=-1
    for s in fr+[h]:
        if s>prev+1: rbands.append((prev+1,s-1))
        prev=s
    cbands=[]; prev=-1
    for s in fc+[w]:
        if s>prev+1: cbands.append((prev+1,s-1))
        prev=s
    return rbands,cbands,fr,fc
