def comp_stats(g,o,n):
    # per block: does a color form a full connected component in the WHOLE grid that covers this block?
    res=[]
    for i in range(n):
        for j in range(n):
            cc=collections.Counter(g[r][c] for r in range(i*3,(i+1)*3) for c in range(j*3,(j+1)*3))
            colout=o[i][j]
            # connected components of colout color in g
            seen=set(); comps=[]
            H,W=len(g),len(g[0])
            for rr in range(H):
                for c_ in range(W):
                    if g[rr][c_]==colout and (rr,c_) not in seen:
                        st=[(rr,c_)]; seen.add((rr,c_)); comp=[]
                        while st:
                            y,x=st.pop(); comp.append((y,x))
                            for dy in(-1,0,1):
                                for dx in(-1,0,1):
                                    ny,nx=y+dy,x+dx
                                    if 0<=ny<H and 0<=nx<W and g[ny][nx]==colout and (ny,nx) not in seen:
                                        seen.add((ny,nx)); st.append((ny,nx))
                        comps.append(comp)
            sizes=[len(c_) for c_ in comps]
            res.append(((i,j),sizes,colout))
    return res
