def comps(grid,val):
    seen=set(); out=[]
    H,W=len(grid),len(grid[0])
    for r in range(H):
        for c in range(W):
            if grid[r][c]==val and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or not(0<=a<H and 0<=b<W) or grid[a][b]!=val: continue
                    seen.add((a,b)); comp.append((a,b))
                    st+= [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
                out.append(sorted(comp))
    return out
