def block_ranges(sc,H,W):
    # gaps between separators: rows/cols not in sc within [0,H) / [0,W)
    return [(a+1,b-1) for a,b in zip([-1]+sc[:-1],sc+[H])] if False else None
def inner_ranges(seps,N):
    # seps = list of separator indices; interior ranges excluding them
    out=[]; prev=-1
    for s in seps+[N]:
        if s>prev+1: out.append((prev+1,s-1))
        prev=s
    return out
